"""Generate a synthetic DOCX for AllDocs round-trip validation.

No PII. Exercises headings, paragraphs, lists, tables, and inline marks.
Output: tests/fixtures/synthetic.docx
"""
from __future__ import annotations

from pathlib import Path

from docx import Document

OUT = Path(__file__).parent / "synthetic.docx"


def main() -> None:
    doc = Document()

    # Title
    doc.add_heading("AllDocs Synthetic DOCX Test", level=1)

    # Subtitle (italic paragraph)
    p = doc.add_paragraph()
    r = p.add_run("A programmatically generated DOCX for round-trip validation.")
    r.italic = True

    # Lead paragraph
    doc.add_paragraph(
        "This document is generated by tests/fixtures/generate_synthetic_docx.py "
        "using python-docx. It contains no personal data and is safe to commit. "
        "Its purpose is to exercise the AllDocs DOCX importer and exporter "
        "end-to-end on a realistic-but-synthetic input."
    )

    # Heading 2
    doc.add_heading("Features tested", level=2)

    # Bulleted list
    for item in [
        "Headings at multiple levels",
        "Paragraphs with mixed inline marks",
        "Bulleted and numbered lists",
        "Tables with cell content",
    ]:
        doc.add_paragraph(item, style="List Bullet")

    # Heading 2 — numbered list
    doc.add_heading("Steps", level=2)
    for item in ["Import the DOCX", "Render in browser", "Round-trip export"]:
        doc.add_paragraph(item, style="List Number")

    # Heading 2 — inline marks
    doc.add_heading("Inline formatting", level=2)
    p = doc.add_paragraph()
    p.add_run("Plain. ")
    p.add_run("Bold. ").bold = True
    p.add_run("Italic. ").italic = True
    r = p.add_run("Bold-italic. ")
    r.bold = True
    r.italic = True
    p.add_run("Underline.").underline = True

    # Heading 2 — table
    doc.add_heading("A small table", level=2)
    table = doc.add_table(rows=3, cols=3)
    try:
        table.style = "Table Grid"
    except KeyError:
        pass
    for i, h in enumerate(["Col A", "Col B", "Col C"]):
        table.rows[0].cells[i].text = h
    table.rows[1].cells[0].text = "Row 1"
    table.rows[1].cells[1].text = "data 1"
    table.rows[1].cells[2].text = "data 2"
    table.rows[2].cells[0].text = "Row 2"
    table.rows[2].cells[1].text = "data 3"
    table.rows[2].cells[2].text = "data 4"

    # Closing italic note
    p = doc.add_paragraph()
    r = p.add_run("End of synthetic test document.")
    r.italic = True

    doc.core_properties.title = "AllDocs Synthetic DOCX Test"
    doc.core_properties.author = "AllDocs project"
    doc.core_properties.subject = "Round-trip validation fixture"

    doc.save(str(OUT))
    print(f"Wrote {OUT} ({OUT.stat().st_size} bytes)")


if __name__ == "__main__":
    main()
